import{_ as o,M as s,p as n,q as i,Q as d,R as e,t,N as l,a3 as a}from"./framework-dd056dd6.js";const h={},c=a('<h1 id="assignment-4-creature-collection-—-make-it-yours" tabindex="-1"><a class="header-anchor" href="#assignment-4-creature-collection-—-make-it-yours" aria-hidden="true">#</a> Assignment 4: Creature Collection — Make It Yours</h1><p><strong>Course:</strong> MTM6302 — Web Development with JavaScript<br><strong>Due:</strong> See Brightspace.</p><h2 id="your-task" tabindex="-1"><a class="header-anchor" href="#your-task" aria-hidden="true">#</a> Your task</h2><p>Create an illustrated creature collection that visitors can personalize. Generate the creature entries with JavaScript, let visitors choose a habitat theme and collection layout, and remember both choices after refreshing the page.</p><p>The supplied HTML, CSS, illustrations, and dataset provide the visual design. Your assessed work is the JavaScript behaviour. You do not need to draw graphics or redesign the page.</p><h2 id="getting-started" tabindex="-1"><a class="header-anchor" href="#getting-started" aria-hidden="true">#</a> Getting started</h2><p><strong>Starter repository:</strong> Link to be added.</p>',7),u=a('<ol><li>Open the starter repository using the link above and select <strong>Fork</strong> to create a copy in your own GitHub account.</li><li>Name your fork <code>mtm6302-a4-creature-collection-YOUR-AC-USERNAME</code>. Replace <code>YOUR-AC-USERNAME</code> with your actual AC username.</li><li>Clone <strong>your fork</strong> to your computer and open it in your editor.</li><li>Keep <code>index.html</code>, <code>style.css</code>, and <code>script.js</code> at the repository root and the supplied images in <code>assets/</code>. The script is linked immediately before the closing <code>&lt;/body&gt;</code> tag.</li><li>Run the page with a local development server. The collection starts empty because you will generate it using JavaScript.</li><li>Read <code>START-HERE.md</code> for the CSS hooks and expected entry structure. Write your work in <code>script.js</code> below the supplied dataset.</li><li>Commit and push your progress to your fork regularly. Follow the submission instructions below to publish your completed site.</li></ol><h2 id="requirements" tabindex="-1"><a class="header-anchor" href="#requirements" aria-hidden="true">#</a> Requirements</h2><h3 id="_1-generate-the-collection" tabindex="-1"><a class="header-anchor" href="#_1-generate-the-collection" aria-hidden="true">#</a> 1. Generate the collection</h3><ul><li>Use the supplied array and a loop to create at least five creature entries. All six supplied creatures may be used.</li><li>Each entry must include its image, meaningful alternative text, name, and description. Descriptions remain in the document even when the compact layout hides them.</li><li>Generate entries with JavaScript rather than writing repeated creature markup into HTML.</li></ul><h3 id="_2-change-the-habitat-theme" tabindex="-1"><a class="header-anchor" href="#_2-change-the-habitat-theme" aria-hidden="true">#</a> 2. Change the habitat theme</h3><p>Use the supplied theme control to choose Enchanted Forest, Moonlit Sky, or Sunset Desert. Apply the matching value to the body&#39;s <code>data-theme</code> attribute. The background artwork, colours, and accents should change immediately.</p><h3 id="_3-change-the-collection-layout" tabindex="-1"><a class="header-anchor" href="#_3-change-the-collection-layout" aria-hidden="true">#</a> 3. Change the collection layout</h3><p>Use the supplied layout control to choose Cards, Detailed List, or Compact List. Apply the matching value to the collection&#39;s <code>data-layout</code> attribute. Keep the same creatures visible; only their presentation changes. Changing preferences must not duplicate entries.</p><h3 id="_4-save-and-restore-preferences" tabindex="-1"><a class="header-anchor" href="#_4-save-and-restore-preferences" aria-hidden="true">#</a> 4. Save and restore preferences</h3><ul><li>Use <code>addEventListener()</code> for control changes. Do not use inline event attributes.</li><li>Save both preferences automatically after a change. Use an assignment-specific Local Storage key.</li><li>Store the preferences together as an object using <code>JSON.stringify()</code> and read them with <code>JSON.parse()</code>.</li><li>On page load, check whether saved data exists before parsing it.</li><li>When saved data exists, restore BOTH the selected control values and the visible appearance.</li><li>When no saved data exists, keep the supplied initial Forest/Cards appearance and show a short message. Do not write default preferences to storage on first load.</li><li>Save preferences only; do not store the catalogue or image files.</li></ul><h3 id="_5-keep-the-interface-usable" tabindex="-1"><a class="header-anchor" href="#_5-keep-the-interface-usable" aria-hidden="true">#</a> 5. Keep the interface usable</h3><p>Retain the labelled controls and responsive styling. Use <code>const</code> and <code>let</code>, readable names, functions with clear responsibilities, and short pseudocode comments. Show a short on-page message when preferences are saved or restored. Browser console errors must not prevent the required interactions.</p><h2 id="test-your-work" tabindex="-1"><a class="header-anchor" href="#test-your-work" aria-hidden="true">#</a> Test your work</h2><table><thead><tr><th>Test</th><th>Expected result</th></tr></thead><tbody><tr><td>Open with the assignment&#39;s storage key absent</td><td>At least five entries, Forest/Cards appearance, no saved-data error, no automatic storage write.</td></tr><tr><td>Select each of the three themes</td><td>The habitat artwork and colours update; the control matches the display.</td></tr><tr><td>Select each of the three layouts</td><td>Cards, detailed rows, and compact rows display the same entries without duplicates.</td></tr><tr><td>Select Moonlit Sky and Compact List, then refresh</td><td>Both controls and the appearance return to those choices.</td></tr><tr><td>Change only the theme, then refresh</td><td>The new theme and previously selected layout are restored.</td></tr><tr><td>Change only the layout, then refresh</td><td>The new layout and previously selected theme are restored.</td></tr><tr><td>Repeat changes and refresh</td><td>The number of entries stays consistent.</td></tr><tr><td>View on a narrow screen</td><td>Controls, images, and names stay readable without horizontal scrolling.</td></tr></tbody></table><h2 id="scope" tabindex="-1"><a class="header-anchor" href="#scope" aria-hidden="true">#</a> Scope</h2><p>Two saved preferences and one generated collection complete the assignment. Fetch, favourites, notes, searching, adding/removing creatures, animation, and a reset button are not required. Handling malformed saved JSON or unavailable storage is an optional extension, not an additional assessment requirement.</p><h2 id="submission" tabindex="-1"><a class="header-anchor" href="#submission" aria-hidden="true">#</a> Submission</h2><ol><li>Complete the requirements, run the test cases, and push your final files to your fork.</li><li>Create a <strong>GitHub Pages site</strong> for your repository: <ul><li>Open <strong>Settings → Pages</strong>.</li><li>Under <strong>Build and deployment</strong>, choose <strong>Deploy from a branch</strong>.</li><li>Select the <strong>main</strong> branch and <strong>/(root)</strong> folder, then select <strong>Save</strong>.</li><li>Ensure <code>index.html</code> is at the root of the publishing branch.</li></ul></li><li>Wait for the site to publish, then open the website URL shown in Pages settings. Confirm that the styles and all creature images load.</li><li>On the published site, change both preferences and refresh. Confirm that the control values and appearance are restored. Preferences saved on your local development site will not transfer to the published site.</li><li>Submit the URL of your <strong>working GitHub Pages website</strong> in Brightspace.</li></ol>',18),p={href:"https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site",target:"_blank",rel:"noopener noreferrer"},g=e("h2",{id:"assessment-focus",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#assessment-focus","aria-hidden":"true"},"#"),t(" Assessment focus")],-1),m=e("p",null,"Dynamic HTML creation; event handling; applying the two preferences; correct JSON and Local Storage use; restoration of control values and appearance; readable code and a working published site.",-1);function b(f,y){const r=s("ExternalLinkIcon");return n(),i("div",null,[c,d(" Instructor: replace the line above with the starter repository link before releasing the assignment. "),u,e("p",null,[t("Submit the published website link, not the repository link or a local development address. No separate report or video is required. See "),e("a",p,[t("GitHub's Pages publishing instructions"),l(r)]),t(" for setup help.")]),g,m])}const w=o(h,[["render",b],["__file","persistent-preferences.html.vue"]]);export{w as default};
